{"file_path": "C:\Users\UserX\Downloads\日志\_research\fetch.py", "content": "import sys, re, html, urllib.request, urllib.parse

UA = ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
      "(KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36")

def fetch(url):
    req = urllib.request.Request(url, headers={
        "User-Agent": UA,
        "Accept-Language": "zh-CN,zh;q=0.9,en;q=0.8",
        "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
    })
    with urllib.request.urlopen(req, timeout=45) as r:
        data = r.read()
    for enc in ("utf-8", "gb18030"):
        try:
            return data.decode(enc)
        except Exception:
            pass
    return data.decode("utf-8", "ignore")

def search(q, out):
    url = "https://cn.bing.com/search?q=" + urllib.parse.quote(q) + "&format=rss&count=30"
    xml = fetch(url)
    items = re.findall(r"<item>(.*?)</item>", xml, re.S)
    lines = ["Q: " + q, "items: %d" % len(items)]
    for i, it in enumerate(items, 1):
        t = re.search(r"<title>(.*?)</title>", it, re.S)
        l = re.search(r"<link>(.*?)</link>", it, re.S)
        d = re.search(r"<description>(.*?)</description>", it, re.S)
        g = lambda m: html.unescape(m.group(1)).strip() if m else ""
        lines.append("[%d] %s" % (i, g(t)))
        lines.append("    URL: %s" % g(l))
        lines.append("    %s" % g(d))
    open(out, "w", encoding="utf-8").write("\n".join(lines) + "\n")

def page(url, out, maxc=30000):
    h = fetch(url)
    raw = re.sub(r"(?is)<(script|style|noscript|svg).*?</\1>", " ", h)
    raw = re.sub(r"(?is)<br\s*/?>|</p>|</div>|</li>|</tr>|</h[1-6]>|</td>", "\n", raw)
    txt = re.sub(r"(?s)<[^>]+>", " ", raw)
    txt = html.unescape(txt)
    txt = re.sub(r"[ \t\u00a0\u3000]+", " ", txt)
    txt = re.sub(r"\n\s*\n+", "\n", txt)
    open(out, "w", encoding="utf-8").write(txt[:maxc])

if __name__ == "__main__":
    mode = sys.argv[1]
    if mode == "search":
        search(sys.argv[2], sys.argv[3])
    elif mode == "page":
        page(sys.argv[2], sys.argv[3], int(sys.argv[4]) if len(sys.argv) > 4 else 30000)
    print("OK")
